import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  mul,
  sub,
  add,
  length,
  div,
  mix,
  color,
  step,
  fract,
  min,
  max,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Float32BufferAttribute, BufferGeometry } = ctx.THREE;

  const root = new Group();
  root.position.set(0, 0.2, 0); // start offset for mount animation

  // --------------------------------------------------------------------------
  // Panel ---------------------------------------------------------------
  const PANEL_W = 3.2;
  const PANEL_H = 2.2;

  const uvNode = uv();

  // radial gradient
  const toCenter = sub(uvNode, vec2(0.5, 0.5));
  const dist = length(toCenter);
  const normDist = div(dist, 0.70710678); // sqrt(0.5²+0.5²)
  const gradient = mix(color('#14141a'), color('#0b0b10'), normDist);

  // grid pattern (0.25‑unit pitch)
  const uvScaled = mul(uvNode, vec2(PANEL_W, PANEL_H));
  const cellSize = 0.25;
  const modX = fract(div(uvScaled.x, cellSize));
  const modY = fract(div(uvScaled.y, cellSize));
  const lineDistX = min(modX, sub(1.0, modX));
  const lineDistY = min(modY, sub(1.0, modY));
  const lineMaskX = step(lineDistX, 0.008);
  const lineMaskY = step(lineDistY, 0.008);
  const lineMask = max(lineMaskX, lineMaskY);
  const gridColor = mul(color('#e8ecf2'), mul(lineMask, 0.06));

  // hairline border
  const edgeX = min(uvNode.x, sub(1.0, uvNode.x));
  const edgeY = min(uvNode.y, sub(1.0, uvNode.y));
  const edgeDist = min(edgeX, edgeY);
  const borderThickness = 0.006 / Math.max(PANEL_W, PANEL_H);
  const borderMask = step(edgeDist, borderThickness);
  const borderColor = mul(color('#26262f'), borderMask);

  const panelColor = add(add(gradient, gridColor), borderColor);
  const panelMaterial = new MeshBasicNodeMaterial({
    color: panelColor,
    transparent: true,
    opacity: 0,
    side: ctx.THREE.DoubleSide,
  });

  const panelGeom = new PlaneGeometry(PANEL_W, PANEL_H);
  const panelMesh = new Mesh(panelGeom, panelMaterial);
  root.add(panelMesh);

  // --------------------------------------------------------------------------
  // Ghost preview -----------------------------------------------------------
  const ghostMat = new MeshBasicNodeMaterial({
    color: color('#e8ecf2'),
    transparent: true,
    opacity: 0.24,
    depthWrite: false,
    wireframe: true,
  });

  const ghostGroup = new Group();

  // Wireframe rectangle 1.1 × 1.4
  const rectMesh = new Mesh(new PlaneGeometry(1.1, 1.4), ghostMat);
  ghostGroup.add(rectMesh);

  // Ghost dial circle (diameter 0.55)
  const dialMesh = new Mesh(new ctx.THREE.CircleGeometry(0.275, 32), ghostMat);
  ghostGroup.add(dialMesh);

  // Two ghost text bars 0.7 w × 0.06 h
  const barGeom = new PlaneGeometry(0.7, 0.06);
  const bar1 = new Mesh(barGeom, ghostMat);
  const bar2 = new Mesh(barGeom, ghostMat);
  bar1.position.set(0, -0.4, 0);
  bar2.position.set(0, -0.55, 0);
  ghostGroup.add(bar1, bar2);

  // Position ghost group left side with padding
  const ghostX = -PANEL_W / 2 + 0.5 + 1.1 / 2;
  ghostGroup.position.set(ghostX, 0, 0.01);
  root.add(ghostGroup);

  // Breathing opacity animation
  const tlGhost = gsap.to(ghostMat, {
    opacity: 0.34,
    duration: 2.4,
    ease: 'cubic-bezier(0.445,0.05,0.55,0.95)',
    repeat: -1,
    yoyo: true,
  });

  // --------------------------------------------------------------------------
  // Text column -------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const textGroup = new Group();
  const columnStartX = -PANEL_W / 2 + 0.5 + 1.1 + 0.5; // left edge + padding + ghost width + padding
  textGroup.position.set(columnStartX, PANEL_H / 2 - 0.6, 0.02); // start near top inside panel

  let cursorY = 0; // local Y inside textGroup

  for (const item of items) {
    const isHeadline = /headline/i.test(item.role ?? '');
    const fontSize = isHeadline ? 34 : 13;
    const fontWeight = isHeadline ? 600 : 400;
    const opts = {
      fontSize,
      color: '#e8ecf2',
      align: 'left',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, opts);
    txtObj.position.set(0, cursorY, 0);
    textGroup.add(txtObj);
    cursorY -= 0.25; // baseline rhythm
  }

  root.add(textGroup);

  // --------------------------------------------------------------------------
  // CTA button --------------------------------------------------------------
  const buttonGroup = new Group();

  // Vertical gradient material
  const btnUv = uv();
  const btnColorNode = mix(color('#ff4450'), color('#c1121f'), btnUv.y);
  const btnMat = new MeshBasicNodeMaterial({
    color: btnColorNode,
    transparent: true,
    opacity: 0,
    side: ctx.THREE.DoubleSide,
  });

  const btnGeom = new PlaneGeometry(1.5, 0.36);
  const btnMesh = new Mesh(btnGeom, btnMat);
  buttonGroup.add(btnMesh);

  // Emissive outline (wireframe)
  const outlineMat = new MeshBasicNodeMaterial({
    color: color('#ff2a38'),
    transparent: false,
    wireframe: true,
  });
  const outlineMesh = new Mesh(btnGeom, outlineMat);
  buttonGroup.add(outlineMesh);

  // Position button below body text
  buttonGroup.position.set(columnStartX + 0.75, cursorY - 0.4, 0.02);
  root.add(buttonGroup);

  // CTA label text
  const ctaText = ctx.fontAtlas.createText(
    'BROWSE THE COLLECTION',
    { fontSize: 13, color: '#e8ecf2', align: 'center' }
  );
  ctaText.position.set(0, 0, 0.01);
  buttonGroup.add(ctaText);

  // Press interaction handlers
  const pressHandlers = {
    pointerdown: () => {
      const tl = gsap.to(buttonGroup.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      buttonGroup.userData.__pressTL = tl;
    },
    pointerup: () => {
      if (buttonGroup.userData.__pressTL) buttonGroup.userData.__pressTL.kill();
      gsap.to(buttonGroup.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
    },
  };
  buttonGroup.userData.handlers = pressHandlers;

  // --------------------------------------------------------------------------
  // Mount animation ---------------------------------------------------------
  const mountMaterials = [panelMaterial, btnMat, ghostMat];
  mountMaterials.forEach((mat) => {
    gsap.to(mat, {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    });
  });
  gsap.to(root.position, {
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });

  // --------------------------------------------------------------------------
  // Cleanup -----------------------------------------------------------------
  root.userData.cleanup = () => {
    // kill timelines
    tlGhost.kill();
    mountMaterials.forEach((mat) => {
      gsap.killTweensOf(mat);
    });
    if (buttonGroup.userData.__pressTL) buttonGroup.userData.__pressTL.kill();

    // dispose geometries
    panelGeom.dispose();
    btnGeom.dispose();

    // dispose materials
    panelMaterial.dispose();
    btnMat.dispose();
    ghostMat.dispose();
    outlineMat.dispose();

    // dispose any child meshes/geometries not covered
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
    });
  };

  return root;
}
